using System;
using System.Diagnostics.CodeAnalysis;
using System.IO;
using System.Threading;
using OpenTabletDriver.Plugin;
using OpenTabletDriver.Plugin.Devices;
using OpenTabletDriver.Plugin.Tablet;

namespace OpenTabletDriver.Devices
{
    public class DeviceReader<T> : IDisposable where T : IDeviceReport
    {
        public DeviceReader(IDeviceEndpoint endpoint, IReportParser<T> reportParser)
        {
            Endpoint = endpoint;
            Parser = reportParser ?? throw new ArgumentNullException(nameof(reportParser));
            workerThread = new Thread(Main)
            {
                Name = "OpenTabletDriver Device Reader",
                IsBackground = true,
                Priority = ThreadPriority.AboveNormal
            };
        }

        private readonly Thread workerThread;
        private bool initialized, connected;

        /// <summary>
        /// The device endpoint in which is reporting data in the <see cref="ReportStream"/>.
        /// </summary>
        public IDeviceEndpoint Endpoint { protected set; get; }

        /// <summary>
        /// The raw device endpoint report stream.
        /// </summary>
        public IDeviceEndpointStream? ReportStream { protected set; get; }

        /// <summary>
        /// The <see cref="IReportParser{T}"/> in which the device reports will be parsed with.
        /// </summary>
        public IReportParser<T> Parser { private set; get; }

        /// <summary>
        /// Whether to make an extra cloned report with data left unmodified.
        /// </summary>
        public bool RawClone { set; get; }

        /// <summary>
        /// Invoked when a new report comes in from the device.
        /// </summary>
        public event EventHandler<T>? Report;

        /// <summary>
        /// Invoked when a new report comes in from the device.
        /// </summary>
        /// <remarks>
        /// This will only be invoked when <see cref="RawClone"/> is set to true.
        /// This report is not meant in any way to be modified, as it is supposed to represent the original data.
        /// </remarks>
        public event EventHandler<T>? RawReport;

        /// <summary>
        /// Whether the device is actively emitting reports and being parsed.
        /// </summary>
        public bool Connected
        {
            protected set
            {
                connected = value;
                ConnectionStateChanged?.Invoke(this, Connected);
            }
            get => connected;
        }

        /// <summary>
        /// Invoked when <see cref="Connected"/> is changed.
        /// </summary>
        public event EventHandler<bool>? ConnectionStateChanged;

        [MemberNotNullWhen(true, nameof(ReportStream))]
        protected virtual bool Initialize()
        {
            try
            {
                ReportStream = Endpoint.Open();
                return true;
            }
            catch (Exception ex)
            {
                Log.Exception(ex);
                return false;
            }
        }

        protected virtual void Start()
        {
            if (!initialized)
                initialized = Initialize();

            if (initialized)
                workerThread.Start();
        }

        protected void Main()
        {
            try
            {
                Connected = true;
                while (Connected)
                {
                    var data = ReportStream!.Read();
                    if (Parser.Parse(data) is T report)
                        OnReport(report);

                    // We create a clone of the report to avoid data being modified on the tablet debugger.
                    if (RawClone && RawReport != null && Parser.Parse(data) is T debugReport)
                        OnRawReport(debugReport);
                }
            }
            catch (ObjectDisposedException dex)
            {
                Log.Debug("Device", $"{(string.IsNullOrWhiteSpace(dex.ObjectName) ? "A device stream" : dex.ObjectName)} was disposed.");
            }
            catch (IOException ioex) when (ioex.Message == "I/O disconnected." || ioex.Message == "Operation failed after some time.")
            {
                Log.Write("Device", "Device disconnected.");
            }
            catch (ArgumentOutOfRangeException)
            {
                Log.Write("Device", "Not enough report data returned by the device. Was it disconnected?");
            }
            catch (Exception ex)
            {
                Log.Exception(ex);
            }
            finally
            {
                Connected = false;
            }
        }

        protected virtual void OnReport(T report) => Report?.Invoke(this, report);
        protected virtual void OnRawReport(T report) => RawReport?.Invoke(this, report);

        public void Dispose()
        {
            Dispose(true);
            GC.SuppressFinalize(this);
        }

        private bool _isDisposed;

        protected virtual void Dispose(bool disposing)
        {
            if (_isDisposed) return;

            if (disposing)
            {
                Connected = false;
                ReportStream?.Dispose();
            }

            _isDisposed = true;
        }
    }
}
using System;
using System.Collections.Generic;
using System.Threading;
using OpenTabletDriver.Devices;
using OpenTabletDriver.Plugin;
using OpenTabletDriver.Plugin.Devices;
using OpenTabletDriver.Plugin.Tablet;

namespace OpenTabletDriver
{
    public class InputDevice : DeviceReader<IDeviceReport>
    {
        private readonly uint _featureInitDelayMs;
        private const string DELAY_ATTRIBUTE_KEY_NAME = "FeatureInitDelayMs";

        public InputDevice(IDriver driver, IDeviceEndpoint device, TabletConfiguration configuration, DeviceIdentifier identifier)
            : base(device, driver.GetReportParser(identifier))
        {
            Endpoint = device;
            Configuration = configuration;
            Identifier = identifier;

            if (Configuration.Attributes?.TryGetValue(DELAY_ATTRIBUTE_KEY_NAME, out var delayStr) ?? false)
                if (!uint.TryParse(delayStr, out _featureInitDelayMs))
                    Log.Write("Device", $"Could not parse '{delayStr}' from attribute {DELAY_ATTRIBUTE_KEY_NAME}", LogLevel.Warning);

            Start();
        }

        /// <summary>
        /// The tablet configuration referring to this device.
        /// </summary>
        public TabletConfiguration Configuration { private set; get; }

        /// <summary>
        /// The device identifier used to detect this device.
        /// </summary>
        /// <value></value>
        public DeviceIdentifier Identifier { private set; get; }

        protected override bool Initialize()
        {
            if (!base.Initialize())
                return false;

            Log.Debug("Device", $"Initializing device '{Endpoint.FriendlyName}' {Endpoint.DevicePath}");
            Log.Debug("Device", $"Using report parser type '{Identifier.ReportParser}'");

            if (_featureInitDelayMs != 0)
                Log.Debug("Device", $"{DELAY_ATTRIBUTE_KEY_NAME} is set in tablet configuration, will sleep for {_featureInitDelayMs}ms between FeatureInitReports");

            foreach (byte index in Identifier.InitializationStrings ?? new List<byte>())
            {
                Endpoint.GetDeviceString(index);
                Log.Debug("Device", $"Initialized string index {index}");
            }

            foreach (var report in Identifier.FeatureInitReport ?? new List<byte[]>())
            {
                if (report.Length == 0)
                    continue;

                try
                {
                    if (_featureInitDelayMs != 0)
                        Thread.Sleep((int)_featureInitDelayMs);
                    ReportStream.SetFeature(report);
                    Log.Debug("Device", "Set device feature: " + BitConverter.ToString(report));
                }
                catch
                {
                    Log.Write("Device", "Failed to set device feature: " + BitConverter.ToString(report), LogLevel.Warning);
                }
            }

            foreach (var report in Identifier.OutputInitReport ?? new List<byte[]>())
            {
                if (report.Length == 0)
                    continue;

                try
                {
                    ReportStream.Write(report);
                    Log.Debug("Device", "Set device output: " + BitConverter.ToString(report));
                }
                catch
                {
                    Log.Write("Device", "Failed to set device output: " + BitConverter.ToString(report), LogLevel.Warning);
                }
            }

            return true;
        }
    }
}

