        IOHIDManagerOpen(manager, 0);
        var set = IOHIDManagerCopyDevices(manager);
        var count = CFSetGetCount(set);
        var values = new IntPtr[count];
        CFSetGetValues(set, values);
        IntPtr target = IntPtr.Zero;
        foreach (var dev in values)
        {
            var vendor = GetInt(dev, "VendorID", -1);
            var product = GetInt(dev, "ProductID", -1);
            var usagePage = GetInt(dev, "PrimaryUsagePage", -1);
            var usage = GetInt(dev, "PrimaryUsage", -1);
