namespace OpenTabletDriver.Devices.MacOSBluetooth
{
    public sealed class WH851MacOSBluetoothEndpointStream : IDeviceEndpointStream
    {
        private const string PACKET_PREFIX = "PACKET ";
        private readonly Process helperProcess;
        private readonly Thread stderrThread;

        public WH851MacOSBluetoothEndpointStream(string helperPath, string nameFilter)
        {
            helperProcess = new Process
            {
                StartInfo = new ProcessStartInfo
                {
                    FileName = helperPath,
                    ArgumentList =
                    {
                        "--name",
                        nameFilter,
                        "--timeout",
                        "86400",
                        "--raw-packets"
                    },
                    RedirectStandardOutput = true,
                    RedirectStandardError = true,
                    UseShellExecute = false
                }
            };

            if (!helperProcess.Start())
                throw new IOException("Unable to start WH851 BLE helper.");

            stderrThread = new Thread(ReadHelperStandardError)
            {
                Name = "WH851 BLE Helper stderr",
                IsBackground = true
            };
            stderrThread.Start();
        }

        public byte[] Read()
        {
            while (!helperProcess.HasExited)
            {
                var line = helperProcess.StandardOutput.ReadLine();
                if (line == null)
                    break;

                Log.Debug("WH851 BLE", line);
                if (line.StartsWith(PACKET_PREFIX, StringComparison.Ordinal))
                    return ParsePacket(line[PACKET_PREFIX.Length..]);
            }

            throw new IOException("I/O disconnected.");
        }

        public void Write(byte[] buffer)
        {
        }

        public void GetFeature(byte[] buffer)
        {
        }

        public void SetFeature(byte[] buffer)
        {
        }

        public void Dispose()
        {
            try
            {
                if (!helperProcess.HasExited)
                    helperProcess.Kill(entireProcessTree: true);
            }
            catch
            {
                // The process may have already exited between HasExited and Kill.
            }
            finally
            {
                helperProcess.Dispose();
            }
        }

        private void ReadHelperStandardError()
        {
            try
            {
                string? line;
                while ((line = helperProcess.StandardError.ReadLine()) != null)
                    Log.Write("WH851 BLE", line, LogLevel.Warning);
            }
            catch (ObjectDisposedException)
            {
            }
        }

        private static byte[] ParsePacket(string hex)
        {
            try
            {
                return hex.Split(' ', StringSplitOptions.RemoveEmptyEntries)
                    .Select(value => byte.Parse(value, NumberStyles.HexNumber, CultureInfo.InvariantCulture))
                    .ToArray();
            }
            catch (Exception ex)
            {
                throw new IOException($"Invalid WH851 BLE packet line: {hex}", ex);
            }
        }
    }
}

import Foundation
import CoreBluetooth

private struct ProbeOptions {
    var nameFilters = ["WH851", "GAOMON", "Gaomon"]
    var identifier: UUID?
    var timeout: TimeInterval = 60
    var logPath: String?
    var listOnly = false
    var rawPackets = false
}

private final class Logger {
    private let fileHandle: FileHandle?
    private let formatter: ISO8601DateFormatter

    init(logPath: String?) {
        formatter = ISO8601DateFormatter()
        formatter.formatOptions = [.withInternetDateTime, .withFractionalSeconds]

        if let logPath {
            FileManager.default.createFile(atPath: logPath, contents: nil)
            fileHandle = FileHandle(forWritingAtPath: logPath)
        } else {
            fileHandle = nil
        }
    }

    deinit {
        try? fileHandle?.close()
    }

    func write(_ message: String) {
        let line = "\(formatter.string(from: Date())) \(message)\n"
        print(line, terminator: "")
        if let data = line.data(using: .utf8) {
            try? fileHandle?.write(contentsOf: data)
        }
    }
}

private extension Data {
    var hexString: String {
        map { String(format: "%02x", $0) }.joined(separator: " ")
    }
}

private extension CBCharacteristicProperties {
    var description: String {
        var values: [String] = []
        if contains(.broadcast) { values.append("broadcast") }
        if contains(.read) { values.append("read") }
        if contains(.writeWithoutResponse) { values.append("writeWithoutResponse") }
        if contains(.write) { values.append("write") }
        if contains(.notify) { values.append("notify") }
        if contains(.indicate) { values.append("indicate") }
        if contains(.authenticatedSignedWrites) { values.append("authenticatedSignedWrites") }
        if contains(.extendedProperties) { values.append("extendedProperties") }
        if contains(.notifyEncryptionRequired) { values.append("notifyEncryptionRequired") }
        if contains(.indicateEncryptionRequired) { values.append("indicateEncryptionRequired") }
        return values.isEmpty ? "none" : values.joined(separator: ",")
    }
}

private final class WH851BleProbe: NSObject, CBCentralManagerDelegate, CBPeripheralDelegate {
    private let options: ProbeOptions
    private let logger: Logger
    private var central: CBCentralManager!
    private var connectedPeripheral: CBPeripheral?
    private var discoveredIdentifiers = Set<UUID>()
    private var subscribedCharacteristics = 0

    init(options: ProbeOptions, logger: Logger) {
        self.options = options
        self.logger = logger
        super.init()
        central = CBCentralManager(delegate: self, queue: .main)
    }

    func centralManagerDidUpdateState(_ central: CBCentralManager) {
        logger.write("central state=\(stateName(central.state))")

        guard central.state == .poweredOn else {
            return
        }

        logger.write("scan start filters=\(options.nameFilters.joined(separator: ",")) identifier=\(options.identifier?.uuidString ?? "-")")
        central.scanForPeripherals(withServices: nil, options: [
            CBCentralManagerScanOptionAllowDuplicatesKey: true
        ])
    }

    func centralManager(_ central: CBCentralManager, didDiscover peripheral: CBPeripheral, advertisementData: [String: Any], rssi RSSI: NSNumber) {
        let advertisedName = advertisementData[CBAdvertisementDataLocalNameKey] as? String
        let displayName = peripheral.name ?? advertisedName ?? "(unnamed)"
        let isFirstDiscovery = discoveredIdentifiers.insert(peripheral.identifier).inserted
        let matched = matches(peripheral: peripheral, advertisedName: advertisedName)

        if isFirstDiscovery || matched {
            logger.write("discover name=\"\(displayName)\" identifier=\(peripheral.identifier.uuidString) rssi=\(RSSI) matched=\(matched) advertisement=\(formatAdvertisement(advertisementData))")
        }

        guard matched else {
            return
        }

        if options.listOnly {
            return
        }

        logger.write("connect name=\"\(displayName)\" identifier=\(peripheral.identifier.uuidString)")
        connectedPeripheral = peripheral
        peripheral.delegate = self
        central.stopScan()
        central.connect(peripheral)
    }

    func centralManager(_ central: CBCentralManager, didConnect peripheral: CBPeripheral) {
        logger.write("connected identifier=\(peripheral.identifier.uuidString)")
        subscribedCharacteristics = 0
        peripheral.discoverServices(nil)
    }

    func centralManager(_ central: CBCentralManager, didFailToConnect peripheral: CBPeripheral, error: Error?) {
        logger.write("connect failed identifier=\(peripheral.identifier.uuidString) error=\(String(describing: error))")
        connectedPeripheral = nil
        central.scanForPeripherals(withServices: nil, options: [
            CBCentralManagerScanOptionAllowDuplicatesKey: true
        ])
    }

    func centralManager(_ central: CBCentralManager, didDisconnectPeripheral peripheral: CBPeripheral, error: Error?) {
        logger.write("disconnected identifier=\(peripheral.identifier.uuidString) error=\(String(describing: error))")
        connectedPeripheral = nil
        central.scanForPeripherals(withServices: nil, options: [
            CBCentralManagerScanOptionAllowDuplicatesKey: true
        ])
    }

    func peripheral(_ peripheral: CBPeripheral, didDiscoverServices error: Error?) {
        if let error {
            logger.write("service discovery error=\(error)")
            return
        }

        let services = peripheral.services ?? []
        logger.write("services count=\(services.count)")
        for service in services {
            logger.write("service uuid=\(service.uuid.uuidString)")
            peripheral.discoverCharacteristics(nil, for: service)
        }
    }

    func peripheral(_ peripheral: CBPeripheral, didDiscoverCharacteristicsFor service: CBService, error: Error?) {
        if let error {
            logger.write("characteristic discovery error service=\(service.uuid.uuidString) error=\(error)")
            return
        }

        for characteristic in service.characteristics ?? [] {
            let properties = characteristic.properties
            let canNotify = properties.contains(.notify) || properties.contains(.indicate)
            let isGaomonLike = service.uuid.uuidString.uppercased().contains("FFE") || characteristic.uuid.uuidString.uppercased().contains("FFE")
            logger.write("characteristic service=\(service.uuid.uuidString) uuid=\(characteristic.uuid.uuidString) properties=\(properties.description) gaomonLike=\(isGaomonLike)")

            if canNotify {
                subscribedCharacteristics += 1
                logger.write("subscribe characteristic=\(characteristic.uuid.uuidString)")
                peripheral.setNotifyValue(true, for: characteristic)
            }
        }

        if subscribedCharacteristics == 0 {
            logger.write("no notifiable characteristics discovered yet")
        }
    }

    func peripheral(_ peripheral: CBPeripheral, didUpdateNotificationStateFor characteristic: CBCharacteristic, error: Error?) {
        logger.write("notification state characteristic=\(characteristic.uuid.uuidString) notifying=\(characteristic.isNotifying) error=\(String(describing: error))")
    }

    func peripheral(_ peripheral: CBPeripheral, didUpdateValueFor characteristic: CBCharacteristic, error: Error?) {
        if let error {
            logger.write("notification error characteristic=\(characteristic.uuid.uuidString) error=\(error)")
            return
        }

        let data = characteristic.value ?? Data()
        if options.rawPackets {
            print("PACKET \(data.hexString)")
        }
        logger.write("notification characteristic=\(characteristic.uuid.uuidString) length=\(data.count) hex=\(data.hexString)")
    }

    private func matches(peripheral: CBPeripheral, advertisedName: String?) -> Bool {
        if let identifier = options.identifier, peripheral.identifier == identifier {
            return true
        }

        let candidates = [peripheral.name, advertisedName].compactMap { $0?.lowercased() }
        return options.nameFilters.contains { filter in
            candidates.contains { $0.contains(filter.lowercased()) }
        }
    }

    private func formatAdvertisement(_ advertisementData: [String: Any]) -> String {
        advertisementData
            .map { key, value in "\(key)=\(value)" }
            .sorted()
            .joined(separator: ";")
    }

    private func stateName(_ state: CBManagerState) -> String {
        switch state {
        case .unknown:
            return "unknown"
        case .resetting:
            return "resetting"
        case .unsupported:
            return "unsupported"
        case .unauthorized:
            return "unauthorized"
        case .poweredOff:
            return "poweredOff"
        case .poweredOn:
            return "poweredOn"
        @unknown default:
            return "unknown(\(state.rawValue))"
        }
    }
}

private func parseOptions(_ arguments: [String]) -> ProbeOptions {
    var options = ProbeOptions()
    var index = 0

    while index < arguments.count {
        let argument = arguments[index]
        switch argument {
        case "--name":
            index += 1
            if index < arguments.count {
                options.nameFilters = arguments[index].split(separator: ",").map(String.init)
            }
        case "--identifier":
            index += 1
            if index < arguments.count {
                options.identifier = UUID(uuidString: arguments[index])
            }
        case "--timeout":
            index += 1
            if index < arguments.count, let timeout = TimeInterval(arguments[index]) {
                options.timeout = timeout
            }
        case "--log":
            index += 1
            if index < arguments.count {
                options.logPath = arguments[index]
            }
        case "--list-only":
            options.listOnly = true
        case "--raw-packets":
            options.rawPackets = true
        case "--help", "-h":
            printUsageAndExit()
        default:
            print("Unknown argument: \(argument)")
            printUsageAndExit(exitCode: 2)
        }

        index += 1
    }

    return options
}

private func printUsageAndExit(exitCode: Int32 = 0) -> Never {
    print("""
    Usage: WH851BleProbe [--name WH851,GAOMON] [--identifier UUID] [--timeout seconds] [--log path] [--list-only] [--raw-packets]

    Scans with CoreBluetooth, connects to a matching WH851-like peripheral, discovers all services and characteristics,
    subscribes to notifiable/indicatable characteristics, and logs notification bytes as timestamped hex.
    With --raw-packets, each notification is also emitted as: PACKET <space-separated-hex>.
    """)
    exit(exitCode)
}

