        public IDictionary<string, string> DeviceAttributes { get; } = new Dictionary<string, string>
        {
            ["Transport"] = "Bluetooth",
            ["TransportGroup"] = "Gaomon WH851",
            ["TransportPriority"] = "10"
        };

        public IDeviceEndpointStream Open() => new WH851MacOSBluetoothEndpointStream(HelperPath, NameFilter);

        public string? GetDeviceString(byte index) => null;

        private static string? ResolveHelperPath(string? helperPath)
        {
            if (!string.IsNullOrWhiteSpace(helperPath))
                return helperPath;

            var bundledPath = Path.Combine(AppContext.BaseDirectory, "WH851BleProbe");
            if (File.Exists(bundledPath))
                return bundledPath;

            var localBuildPath = Path.Combine(Environment.CurrentDirectory, "bin", "tools", "macos", "WH851BleProbe");
            if (File.Exists(localBuildPath))
                return localBuildPath;

            return null;
        }
    }
