namespace OpenTabletDriver.Configurations.Parsers.Huion
{
    public class WH851BluetoothReportParser : IReportParser<IDeviceReport>
    {
        private const float MaxX = 40640;
        private const float MaxY = 25400;
        private const float MacOSHidPointerScale = 200;

        private readonly InspiroyReportParser inspiroyReportParser = new();
        private Vector2 macOSHidPosition = new(MaxX / 2, MaxY / 2);

        public IDeviceReport Parse(byte[] data)
        {
            if (data.Length >= 12 && data[0] == 0x08)
                return inspiroyReportParser.Parse(data);

            if (data.Length >= 10 && data[0] == 0x0a)
            {
                if (!data[1].IsBitSet(6))
                    return new OutOfRangeReport(data);

                return new WH851BluetoothPenReport(data);
            }

            if (data.Length >= 10 && data[0] == 0x03 && data[1] == 0xf1)
                return ParseMacOSHidPointerReport(data);

            return new DeviceReport(data);
        }

        private WH851MacOSHidPointerReport ParseMacOSHidPointerReport(byte[] data)
        {
            var deltaX = Unsafe.ReadUnaligned<short>(ref data[3]);
            var deltaY = Unsafe.ReadUnaligned<short>(ref data[5]);

            macOSHidPosition = new Vector2
            {
                X = Math.Clamp(macOSHidPosition.X + deltaX * MacOSHidPointerScale, 0, MaxX),
                Y = Math.Clamp(macOSHidPosition.Y + deltaY * MacOSHidPointerScale, 0, MaxY)
            };

            return new WH851MacOSHidPointerReport(data, macOSHidPosition);
        }
    }

    public struct WH851BluetoothPenReport : ITabletReport, ITiltReport, IEraserReport
    {
        public WH851BluetoothPenReport(byte[] report)
        {
            Raw = report;
            Position = new Vector2
            {
                X = Unsafe.ReadUnaligned<ushort>(ref report[2]),
                Y = Unsafe.ReadUnaligned<ushort>(ref report[4])
            };
            Pressure = Unsafe.ReadUnaligned<ushort>(ref report[6]);
            Tilt = new Vector2
            {
                X = (sbyte)report[8],
                Y = (sbyte)report[9]
            };

            PenButtons =
            [
                report[1].IsBitSet(1),
                report[1].IsBitSet(2)
            ];
            Eraser = report[1].IsBitSet(2);
        }

        public byte[] Raw { get; set; }
        public Vector2 Position { get; set; }
        public Vector2 Tilt { get; set; }
        public uint Pressure { get; set; }
        public bool[] PenButtons { get; set; }
        public bool Eraser { get; set; }
    }

    public struct WH851MacOSHidPointerReport : ITabletReport
