using System.Threading;

internal static class Program
{
    private const int kIOHIDEventTypeDigitizer = 11;
    private const int DigitizerBase = kIOHIDEventTypeDigitizer << 16;
    private const int DigitizerX = DigitizerBase + 0;
    private const int DigitizerY = DigitizerBase + 1;
    private const int DigitizerButtonMask = DigitizerBase + 3;
    private const int DigitizerEventMask = DigitizerBase + 7;
    private const int DigitizerRange = DigitizerBase + 8;
    private const int DigitizerTouch = DigitizerBase + 9;
    private const int DigitizerPressure = DigitizerBase + 10;
    private const int DigitizerTiltX = DigitizerBase + 13;
    private const int DigitizerTiltY = DigitizerBase + 14;

    private static readonly IOHIDEventCallback Callback = OnEvent;
    private static int eventCount;

    private static void Main()
    {
        Console.WriteLine("creating event client");
        var client = IOHIDEventSystemClientCreate(IntPtr.Zero);
        Console.WriteLine($"client=0x{client.ToInt64():x}");
        if (client == IntPtr.Zero)
            return;

        IOHIDEventSystemClientRegisterEventCallback(client, Callback, IntPtr.Zero, IntPtr.Zero);
        Console.WriteLine("registered callback");
        IOHIDEventSystemClientScheduleWithRunLoop(client, CFRunLoopGetCurrent(), CFRunLoopDefaultMode);
        Console.WriteLine("scheduled run loop");
        IOHIDEventSystemClientActivate(client);
        Console.WriteLine("LISTENING: move the WH851 pen now");

        var deadline = DateTime.UtcNow.AddSeconds(30);
        while (DateTime.UtcNow < deadline)
            CFRunLoopRunInMode(CFRunLoopDefaultMode, 0.25, false);

        Console.WriteLine($"done events={eventCount}");
    }

    private static bool OnEvent(IntPtr target, IntPtr refcon, IntPtr sender, IntPtr eventRef)
    {
        var type = IOHIDEventGetType(eventRef);
        if (type != kIOHIDEventTypeDigitizer)
            return false;

        var n = Interlocked.Increment(ref eventCount);
        if (n <= 80)
        {
            var x = IOHIDEventGetFloatValue(eventRef, DigitizerX);
            var y = IOHIDEventGetFloatValue(eventRef, DigitizerY);
            var pressure = IOHIDEventGetFloatValue(eventRef, DigitizerPressure);
            var tiltX = IOHIDEventGetFloatValue(eventRef, DigitizerTiltX);
            var tiltY = IOHIDEventGetFloatValue(eventRef, DigitizerTiltY);
            var buttons = IOHIDEventGetIntegerValue(eventRef, DigitizerButtonMask);
            var mask = IOHIDEventGetIntegerValue(eventRef, DigitizerEventMask);
            var range = IOHIDEventGetIntegerValue(eventRef, DigitizerRange);
            var touch = IOHIDEventGetIntegerValue(eventRef, DigitizerTouch);
            Console.WriteLine($"digitizer #{n}: x={x:0.000000} y={y:0.000000} p={pressure:0.000000} tilt=({tiltX:0.000},{tiltY:0.000}) buttons=0x{buttons:X} mask=0x{mask:X} range={range} touch={touch}");
