    private const int kCFRunLoopCommonModes = 0;
    private const int kCGEventTabletPointer = 23;
    private const int kCGEventTabletProximity = 24;
    private const int kCGTabletEventPointX = 15;
    private const int kCGTabletEventPointY = 16;
