using System;
using System.Runtime.InteropServices;
using System.Text;
using System.Threading;

internal static class Program
{
    private static readonly IOHIDReportCallback Callback = OnReport;
    private static int reportCount;

    private static void Main()
    {
        var manager = IOHID.IOHIDManagerCreate(IntPtr.Zero, 0);
        IOHID.IOHIDManagerSetDeviceMatching(manager, IntPtr.Zero);
        IOHID.IOHIDManagerOpen(manager, 0);
        var set = IOHID.IOHIDManagerCopyDevices(manager);
        var count = IOHID.CFSetGetCount(set);
        var values = new IntPtr[count];
        IOHID.CFSetGetValues(set, values);
        foreach (var device in values)
        {
            if (IOHID.IntProp(device, "VendorID") != 0x256c || IOHID.IntProp(device, "ProductID") != 0x8251)
                continue;
            var page = IOHID.IntProp(device, "PrimaryUsagePage");
            var usage = IOHID.IntProp(device, "PrimaryUsage");
            if (page != 13 || usage != 2)
                continue;

            Console.WriteLine($"using digitizer {IOHID.StringProp(device, "Product")} usage={page}/{usage}");
            var len = Math.Max(IOHID.IntProp(device, "MaxInputReportSize", 10), 10);
            var buffer = Marshal.AllocHGlobal(len);
            IOHID.IOHIDDeviceRegisterInputReportCallback(device, buffer, len, Callback, IntPtr.Zero);
            IOHID.IOHIDDeviceScheduleWithRunLoop(device, IOHID.CFRunLoopGetCurrent(), IOHID.CFRunLoopDefaultMode);
            Console.WriteLine("LISTENING: move the WH851 pen now");
            var deadline = DateTime.UtcNow.AddSeconds(30);
            while (DateTime.UtcNow < deadline)
                IOHID.CFRunLoopRunInMode(IOHID.CFRunLoopDefaultMode, 0.25, false);
            Console.WriteLine($"done reports={reportCount}");
            return;
        }
        Console.WriteLine("digitizer not found");
    }

    private static void OnReport(IntPtr context, int result, IntPtr sender, int type, uint reportId, IntPtr report, nint reportLength)
    {
        var n = Interlocked.Increment(ref reportCount);
        var data = new byte[(int)reportLength];
        Marshal.Copy(report, data, 0, data.Length);
        if (reportId != 0 && (data.Length == 0 || data[0] != reportId))
            data = [(byte)reportId, .. data];
        if (n <= 120)
            Console.WriteLine($"report #{n}: result=0x{result:X} type={type} id={reportId} len={reportLength} {BitConverter.ToString(data)}");
    }

    [UnmanagedFunctionPointer(CallingConvention.Cdecl)]
    private delegate void IOHIDReportCallback(IntPtr context, int result, IntPtr sender, int type, uint reportId, IntPtr report, nint reportLength);
}

internal static class IOHID
{
    private const string IOKit = "/System/Library/Frameworks/IOKit.framework/IOKit";
    private const string CF = "/System/Library/Frameworks/CoreFoundation.framework/CoreFoundation";
    private const uint UTF8 = 0x08000100;
    private const int SInt32 = 3;
    private static readonly nint NumberType = CFNumberGetTypeID();
    private static readonly nint StringType = CFStringGetTypeID();
    private static IntPtr defaultMode;

    [DllImport(IOKit)] public static extern IntPtr IOHIDManagerCreate(IntPtr allocator, int options);
    [DllImport(IOKit)] public static extern void IOHIDManagerSetDeviceMatching(IntPtr manager, IntPtr matching);
    [DllImport(IOKit)] public static extern int IOHIDManagerOpen(IntPtr manager, int options);
    [DllImport(IOKit)] public static extern IntPtr IOHIDManagerCopyDevices(IntPtr manager);
    [DllImport(IOKit)] public static extern IntPtr IOHIDDeviceGetProperty(IntPtr device, IntPtr key);
    [DllImport(IOKit)] public static extern void IOHIDDeviceRegisterInputReportCallback(IntPtr device, IntPtr report, nint reportLength, Program_IOHIDReportCallback callback, IntPtr context);
    public delegate void Program_IOHIDReportCallback(IntPtr context, int result, IntPtr sender, int type, uint reportId, IntPtr report, nint reportLength);
    [DllImport(IOKit)] public static extern void IOHIDDeviceScheduleWithRunLoop(IntPtr device, IntPtr runLoop, IntPtr runLoopMode);
    [DllImport(CF)] public static extern nint CFSetGetCount(IntPtr set);
    [DllImport(CF)] public static extern void CFSetGetValues(IntPtr set, [Out] IntPtr[] values);
    [DllImport(CF)] public static extern IntPtr CFStringCreateWithCString(IntPtr allocator, string value, uint encoding);
    [DllImport(CF)] public static extern bool CFNumberGetValue(IntPtr number, int type, out int value);
    [DllImport(CF)] public static extern bool CFStringGetCString(IntPtr value, StringBuilder buffer, long bufferSize, uint encoding);
    [DllImport(CF)] public static extern nint CFGetTypeID(IntPtr value);
    [DllImport(CF)] public static extern nint CFNumberGetTypeID();
    [DllImport(CF)] public static extern nint CFStringGetTypeID();
    [DllImport(CF)] public static extern void CFRelease(IntPtr value);
    [DllImport(CF)] public static extern IntPtr CFRunLoopGetCurrent();
    [DllImport(CF)] public static extern int CFRunLoopRunInMode(IntPtr mode, double seconds, bool returnAfterSourceHandled);
    [DllImport("/usr/lib/libSystem.dylib")] private static extern IntPtr dlopen(string path, int mode);
    [DllImport("/usr/lib/libSystem.dylib")] private static extern IntPtr dlsym(IntPtr handle, string symbol);

    public static IntPtr CFRunLoopDefaultMode => defaultMode == IntPtr.Zero ? defaultMode = Marshal.ReadIntPtr(dlsym(dlopen(CF, 0), "kCFRunLoopDefaultMode")) : defaultMode;

    public static int IntProp(IntPtr d, string key, int fallback = -1) { var k = CFStringCreateWithCString(IntPtr.Zero, key, UTF8); var p = IOHIDDeviceGetProperty(d, k); CFRelease(k); return p != IntPtr.Zero && CFGetTypeID(p) == NumberType && CFNumberGetValue(p, SInt32, out int value) ? value : fallback; }
    public static string? StringProp(IntPtr d, string key) { var k = CFStringCreateWithCString(IntPtr.Zero, key, UTF8); var p = IOHIDDeviceGetProperty(d, k); CFRelease(k); if (p == IntPtr.Zero || CFGetTypeID(p) != StringType) return null; var b = new StringBuilder(256); return CFStringGetCString(p, b, b.Capacity, UTF8) ? b.ToString() : null; }
}
