{"cmd":"tmpdir=$(mktemp -d /tmp/wh851-cbconnected.XXXXXX)
cat > "$tmpdir/WH851ConnectedProbe.swift" <<'SWIFT'
import Foundation
import CoreBluetooth

final class Probe: NSObject, CBCentralManagerDelegate, CBPeripheralDelegate {
    var central: CBCentralManager!
    var done = false
    var packetCount = 0
    let hidService = CBUUID(string: "1812")

    override init() {
        super.init()
        central = CBCentralManager(delegate: self, queue: nil)
    }

    func centralManagerDidUpdateState(_ central: CBCentralManager) {
        print("central state \(central.state.rawValue)")
        guard central.state == .poweredOn else { return }

        let connected = central.retrieveConnectedPeripherals(withServices: [hidService])
        print("connected HID peripherals: \(connected.count)")
        for peripheral in connected {
            print("candidate name=\(peripheral.name ?? "<nil>") id=\(peripheral.identifier.uuidString)")
            if (peripheral.name ?? "").contains("WH851") {
                peripheral.delegate = self
                central.connect(peripheral, options: nil)
                return
            }
        }
        print("WH851 not found from retrieveConnectedPeripherals")
        done = true
    }

    func centralManager(_ central: CBCentralManager, didConnect peripheral: CBPeripheral) {
        print("connected \(peripheral.name ?? "<nil>")")
        peripheral.discoverServices(nil)
    }

    func centralManager(_ central: CBCentralManager, didFailToConnect peripheral: CBPeripheral, error: Error?) {
        print("connect failed \(String(describing: error))")
        done = true
    }

    func peripheral(_ peripheral: CBPeripheral, didDiscoverServices error: Error?) {
        if let error { print("discover services error \(error)") }
        for service in peripheral.services ?? [] {
            print("service \(service.uuid.uuidString)")
            peripheral.discoverCharacteristics(nil, for: service)
        }
    }

    func peripheral(_ peripheral: CBPeripheral, didDiscoverCharacteristicsFor service: CBService, error: Error?) {
        if let error { print("discover chars error \(error)") }
        for characteristic in service.characteristics ?? [] {
            let props = characteristic.properties
            print("char service=\(service.uuid.uuidString) uuid=\(characteristic.uuid.uuidString) props=0x\(String(props.rawValue, radix: 16))")
            if props.contains(.notify) || props.contains(.indicate) {
                print("subscribe \(characteristic.uuid.uuidString)")
                peripheral.setNotifyValue(true, for: characteristic)
            }
        }
        DispatchQueue.main.asyncAfter(deadline: .now() + 2.0) {
            print("LISTENING: move the WH851 pen now")
        }
        DispatchQueue.main.asyncAfter(deadline: .now() + 32.0) {
            self.done = true
        }
    }

    func peripheral(_ peripheral: CBPeripheral, didUpdateNotificationStateFor characteristic: CBCharacteristic, error: Error?) {
        print("notify state uuid=\(characteristic.uuid.uuidString) isNotifying=\(characteristic.isNotifying) error=\(String(describing: error))")
    }

    func peripheral(_ peripheral: CBPeripheral, didUpdateValueFor characteristic: CBCharacteristic, error: Error?) {
        if let error { print("update error \(error)") }
        guard let data = characteristic.value else { return }
        packetCount += 1
        let hex = data.map { String(format: "%02X", $0) }.joined(separator: "-")
        print("packet #\(packetCount) char=\(characteristic.uuid.uuidString) len=\(data.count) \(hex)")
    }
}

let probe = Probe()
let until = Date().addingTimeInterval(45)
while !probe.done && Date() < until {
    RunLoop.main.run(mode: .default, before: Date().addingTimeInterval(0.1))
}
print("done packets=\(probe.packetCount)")
