import IOKit.hid

let vendorID = 0x256c
let productID = 0x8251
let usagePageDigitizer = 0x000d
let usageDigitizer = 0x0002
let durationSeconds: TimeInterval = 35

func cfnum(_ value: Int) -> CFNumber {
    var v = value
    return CFNumberCreate(kCFAllocatorDefault, .intType, &v)
}

func intProp(_ obj: CFTypeRef, _ key: CFString) -> Int? {
    guard CFGetTypeID(obj) == CFNumberGetTypeID() else { return nil }
    var v: Int = 0
    CFNumberGetValue((obj as! CFNumber), .intType, &v)
    return v
}

func propInt(_ element: IOHIDElement, _ key: CFString) -> Int {
    guard let value = IOHIDElementGetProperty(element, key) else { return 0 }
    return intProp(value, key) ?? 0
}

func valueInt(_ device: IOHIDDevice, _ element: IOHIDElement) -> Int? {
    var value: IOHIDValue?
    let result = IOHIDDeviceGetValue(device, element, &value)
    guard result == kIOReturnSuccess, let value else { return nil }
    return IOHIDValueGetIntegerValue(value)
}

let manager = IOHIDManagerCreate(kCFAllocatorDefault, IOOptionBits(kIOHIDOptionsTypeNone))
let match: [CFString: Any] = [
    kIOHIDVendorIDKey: cfnum(vendorID),
    kIOHIDProductIDKey: cfnum(productID),
    kIOHIDPrimaryUsagePageKey: cfnum(usagePageDigitizer),
    kIOHIDPrimaryUsageKey: cfnum(usageDigitizer)
]
IOHIDManagerSetDeviceMatching(manager, match as CFDictionary)
IOHIDManagerScheduleWithRunLoop(manager, CFRunLoopGetCurrent(), CFRunLoopMode.defaultMode.rawValue)
IOHIDManagerOpen(manager, IOOptionBits(kIOHIDOptionsTypeNone))
CFRunLoopRunInMode(.defaultMode, 0.5, false)

guard let devices = IOHIDManagerCopyDevices(manager) as? Set<IOHIDDevice>, let device = devices.first else {
    FileHandle.standardError.write(Data("no WH851 digitizer endpoint found\n".utf8))
    exit(2)
}

let deviceName = IOHIDDeviceGetProperty(device, kIOHIDProductKey as CFString) as? String ?? "unknown"
FileHandle.standardOutput.write(Data("device=\(deviceName)\n".utf8))

let openResult = IOHIDDeviceOpen(device, IOOptionBits(kIOHIDOptionsTypeNone))
FileHandle.standardOutput.write(Data(String(format: "open=0x%08x\n", openResult).utf8))

let all = (IOHIDDeviceCopyMatchingElements(device, nil, IOOptionBits(kIOHIDOptionsTypeNone)) as? [IOHIDElement]) ?? []
let inputs = all.filter {
    let type = IOHIDElementGetType($0)
    return type == kIOHIDElementTypeInput_Misc ||
        type == kIOHIDElementTypeInput_Button ||
        type == kIOHIDElementTypeInput_Axis ||
        type == kIOHIDElementTypeInput_ScanCodes
}

FileHandle.standardOutput.write(Data("input elements=\(inputs.count)\n".utf8))
for (index, element) in inputs.enumerated() {
    let page = IOHIDElementGetUsagePage(element)
    let usage = IOHIDElementGetUsage(element)
    let min = IOHIDElementGetLogicalMin(element)
    let max = IOHIDElementGetLogicalMax(element)
    let current = valueInt(device, element).map(String.init) ?? "nil"
    FileHandle.standardOutput.write(Data(String(format: "el[%02d] page=0x%04x usage=0x%04x log=%ld..%ld value=%@\n", index, page, usage, min, max, current).utf8))
}

FileHandle.standardOutput.write(Data("LISTENING: move WH851 pen across the tablet now\n".utf8))
let end = Date().addingTimeInterval(durationSeconds)
var last: [Int: Int] = [:]
var changes = 0

while Date() < end && changes < 300 {
    for (index, element) in inputs.enumerated() {
        guard let v = valueInt(device, element) else { continue }
        if last[index] != v {
            last[index] = v
            changes += 1
            let page = IOHIDElementGetUsagePage(element)
            let usage = IOHIDElementGetUsage(element)
            FileHandle.standardOutput.write(Data(String(format: "change #%03d el[%02d] page=0x%04x usage=0x%04x value=%d\n", changes, index, page, usage, v).utf8))
        }
    }
    usleep(20_000)
}

