                    var productId = IOHID.GetIntProperty(device, "ProductID", -1);
                    var usagePage = IOHID.GetIntProperty(device, "PrimaryUsagePage", -1);
                    var usage = IOHID.GetIntProperty(device, "PrimaryUsage", -1);

