            var requested = IOHID.IOHIDRequestAccess(IOHID.IOHIDRequestTypeListenEvent);
            access = IOHID.IOHIDCheckAccess(IOHID.IOHIDRequestTypeListenEvent);
            if (access == IOHID.IOHIDAccessTypeGranted)
