        case kCGEventOtherMouseDown: return "OtherDown";
        case kCGEventOtherMouseUp: return "OtherUp";
        default: return "Other";
    }
}

static CGEventRef callback(CGEventTapProxy proxy, CGEventType type, CGEventRef event, void *refcon) {
    if (type == kCGEventTapDisabledByTimeout || type == kCGEventTapDisabledByUserInput) {
        CGEventTapEnable((CFMachPortRef)refcon, true);
        return event;
    }

    CGPoint p = CGEventGetLocation(event);
    int64_t subtype = CGEventGetIntegerValueField(event, kCGMouseEventSubtype);
    int64_t dx = CGEventGetIntegerValueField(event, kCGMouseEventDeltaX);
    int64_t dy = CGEventGetIntegerValueField(event, kCGMouseEventDeltaY);
    int64_t tx = CGEventGetIntegerValueField(event, kCGTabletEventPointX);
    int64_t ty = CGEventGetIntegerValueField(event, kCGTabletEventPointY);
    int64_t pressure = CGEventGetIntegerValueField(event, kCGTabletEventPointPressure);
    int64_t buttons = CGEventGetIntegerValueField(event, kCGTabletEventPointButtons);
    int64_t vendor1 = CGEventGetIntegerValueField(event, kCGTabletEventVendor1);
    int64_t vendor2 = CGEventGetIntegerValueField(event, kCGTabletEventVendor2);
    int64_t vendor3 = CGEventGetIntegerValueField(event, kCGTabletEventVendor3);

    printf("EVENT type=%s(%u) loc=%.1f,%.1f subtype=%lld d=%lld,%lld tablet=%lld,%lld pressure=%lld buttons=0x%llx vendor=%lld,%lld,%lld\n",
           nameForType(type), type, p.x, p.y, subtype, dx, dy, tx, ty, pressure, buttons, vendor1, vendor2, vendor3);
    fflush(stdout);
    return event;
}

int main(void) {
    CGEventMask mask = CGEventMaskBit(kCGEventMouseMoved) |
                       CGEventMaskBit(kCGEventLeftMouseDragged) |
                       CGEventMaskBit(kCGEventRightMouseDragged) |
                       CGEventMaskBit(kCGEventOtherMouseDragged) |
                       CGEventMaskBit(kCGEventScrollWheel) |
                       CGEventMaskBit(kCGEventTabletPointer) |
                       CGEventMaskBit(kCGEventTabletProximity) |
                       CGEventMaskBit(kCGEventLeftMouseDown) |
                       CGEventMaskBit(kCGEventLeftMouseUp) |
                       CGEventMaskBit(kCGEventRightMouseDown) |
                       CGEventMaskBit(kCGEventRightMouseUp) |
                       CGEventMaskBit(kCGEventOtherMouseDown) |
                       CGEventMaskBit(kCGEventOtherMouseUp);
    CFMachPortRef tap = CGEventTapCreate(kCGSessionEventTap, kCGHeadInsertEventTap, kCGEventTapOptionListenOnly, mask, callback, NULL);
    if (!tap) {
        fprintf(stderr, "failed to create event tap; Input Monitoring may be missing for Terminal/Codex\n");
        return 2;
    }
    CFRunLoopSourceRef source = CFMachPortCreateRunLoopSource(kCFAllocatorDefault, tap, 0);
    CFRunLoopAddSource(CFRunLoopGetCurrent(), source, kCFRunLoopCommonModes);
    CGEventTapEnable(tap, true);
    CFRunLoopRunInMode(kCFRunLoopDefaultMode, 20.0, false);
    CFRelease(source);
    CFRelease(tap);
    return 0;
}
